package com.cpf.batch.runtime; import com.cpf.batch.api.*; import org.slf4j.*; import org.springframework.context.SmartLifecycle; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.web.client.RestClient; import java.time.Instant; import java.util.concurrent.atomic.AtomicBoolean;
public final class RuntimeReporter implements SmartLifecycle { private static final Logger log=LoggerFactory.getLogger(RuntimeReporter.class); private final RuntimeRegistration reg; private final RuntimeStateProvider state; private final RestClient client; private final AtomicBoolean running=new AtomicBoolean(); public RuntimeReporter(RuntimeRegistration r,RuntimeStateProvider s,RestClient.Builder b,String u){reg=r;state=s;client=b.baseUrl(u).build();} public void start(){running.set(true);try{client.post().uri("/api/v1/batch/runtime/registrations").body(reg).retrieve().toBodilessEntity();}catch(RuntimeException e){log.warn("runtime registration unavailable instance={} cause={}",reg.instanceId(),SensitiveTextSanitizer.sanitize(e.getMessage()));}} @Scheduled(fixedDelayString="${cpf.batch.runtime.heartbeat-ms:5000}") public void heartbeat(){if(!running.get())return;RuntimeHeartbeat h=new RuntimeHeartbeat(reg.instanceId(),Instant.now(),state.actualState(),state.ready(),state.currentExecutions(),state.activeLeases(),state.availableCapacity(),state.queueDepth(),state.draining(),state.dependencyHealth(),state.lastErrorCode(),state.metrics(),reg.artifactVersion(),state.fencingToken());try{client.post().uri("/api/v1/batch/runtime/heartbeats").body(h).retrieve().toBodilessEntity();}catch(RuntimeException e){log.warn("runtime heartbeat unavailable instance={} cause={}",reg.instanceId(),SensitiveTextSanitizer.sanitize(e.getMessage()));}} public void stop(){running.set(false);} public boolean isRunning(){return running.get();} }
